package finance.network;

import finance.bank.*;import finance.company.*;import finance.cycle.EconomyCycleService;import finance.debt.*;import finance.policy.MonetaryPolicyService;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.*;import java.util.*;import java.util.function.Supplier;
public record BankRequestPacket(long requestId){public static void encode(BankRequestPacket p,FriendlyByteBuf b){b.writeLong(p.requestId);}public static BankRequestPacket decode(FriendlyByteBuf b){return new BankRequestPacket(b.readLong());}public static void handle(BankRequestPacket p,Supplier<NetworkEvent.Context>s){var c=s.get();c.enqueueWork(()->send(p,c.getSender()));c.setPacketHandled(true);}private static void send(BankRequestPacket p,ServerPlayer player){if(player==null||p.requestId<=0||!MarketDataRequestLimiter.allow(player.getUUID(),player.server.getTickCount(),"bank-request"))return;BankingManager.ensureDefaultBanks();UUID owner=player.getUUID();boolean admin=player.hasPermissions(2);Company company=CompanyManager.getCompanyByOwner(owner);List<BankResponsePacket.BankRow>banks=BankingManager.banks().values().stream().limit(BankResponsePacket.MAX_ROWS).map(bank->{var x=PublicBankViewService.crop(bank,admin);return new BankResponsePacket.BankRow(x.id(),x.code(),x.name(),x.status(),x.assets(),x.reserves(),x.requiredReserves(),x.deposits(),x.equity(),x.capitalBps(),x.liquidityBps(),x.demandRateBps(),x.timeRateBps(),x.centralBorrowing());}).toList();List<BankResponsePacket.AccountRow>accounts=BankingManager.accounts().values().stream().filter(a->a.ownerId().equals(owner)||company!=null&&a.ownerId().equals(company.getCompanyId())).limit(BankResponsePacket.MAX_ROWS).map(a->new BankResponsePacket.AccountRow(a.id(),a.bankId(),a.ownerType(),a.type(),a.balance(),a.frozen())).toList();List<BankResponsePacket.TimeRow>terms=BankingManager.timeDeposits().values().stream().filter(t->t.ownerId().equals(owner)).limit(BankResponsePacket.MAX_ROWS).map(t->new BankResponsePacket.TimeRow(t.id(),t.bankId(),t.principal(),t.lockedRateBps(),t.maturityDay(),t.accruedInterest(),t.status())).toList();List<BankResponsePacket.LoanRow>loans=CompanyLoanManager.loans().values().stream().filter(l->company!=null&&l.companyId().equals(company.getCompanyId())||admin).limit(BankResponsePacket.MAX_ROWS).map(l->new BankResponsePacket.LoanRow(l.id(),l.companyId(),l.lenderType(),l.lenderId(),l.outstandingPrincipal(),l.accruedInterest(),l.annualRateBasisPoints(),l.maturityDay(),l.status())).toList();var response=new BankResponsePacket(p.requestId,admin,admin?DepositInsuranceService.fund():finance.config.FinanceConfig.bankInsuranceLimit(),InterbankMarketService.overnightRateBasisPoints(),banks,accounts,terms,loans);FinancePacketHandler.CHANNEL.send(PacketDistributor.PLAYER.with(()->player),response);}}
